<?php
require_once __DIR__.'/auth.php';
if(!isAdmin()){http_response_code(403);exit('Khusus Admin.');}
require_once __DIR__.'/pembaruan_helper.php';
$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{layananValidasiToken();$db->beginTransaction();$newId=prosesReschedulingPinjaman($db,(int)($_POST['pinjaman_id']??0),(int)$_SESSION['user_id'],(string)($_POST['alasan']??''));$db->commit();$_SESSION['success']='Rescheduling berhasil. Jadwal baru: '.$newId.'.';}
    catch(Throwable $e){if($db->inTransaction())$db->rollBack();$_SESSION['error']=$e->getMessage();}
    header('Location: rescheduling.php');exit;
}
$rows=$db->query("SELECT p.id,p.kode_pinjaman,p.jumlah_pinjaman,p.sisa_pokok,p.tenor,p.bunga,p.frekuensi,a.nama_lengkap,a.kode_anggota FROM pinjaman p JOIN anggota a ON a.id=p.anggota_id WHERE p.status IN ('aktif','macet') ORDER BY p.id DESC")->fetchAll(PDO::FETCH_ASSOC);
$data=[];foreach($rows as $r){$k=hitungDPDPinjaman($db,(int)$r['id']);if(in_array($k['kol'],[2,3,4],true)){$profit=$db->prepare("SELECT COALESCE(SUM(GREATEST(0,x.bunga-COALESCE(y.paid,0))),0) FROM angsuran x LEFT JOIN (SELECT angsuran_id,SUM(bunga) paid FROM pembayaran_angsuran_alokasi GROUP BY angsuran_id) y ON y.angsuran_id=x.id WHERE x.pinjaman_id=? AND x.status<>'lunas'");$profit->execute([$r['id']]);$r['dpd']=$k['dpd'];$r['kol']=$k['kol'];$r['keuntungan_tersisa']=(float)$profit->fetchColumn();$r['tenor_baru']=(int)$r['tenor']*2;$r['cicilan_baru']=(int)$r['tenor_baru']*($r['frekuensi']==='mingguan'?4:($r['frekuensi']==='dua_mingguan'?2:1));$data[]=$r;}}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rescheduling Pinjaman</title><?php $uiAssetPrefix='../';include __DIR__.'/layout/assets.php';?></head><body><?php include __DIR__.'/layout/shell_start.php';?><div class="ui-tx-page"><header class="ui-dash-header"><div class="ui-dash-header-icon"><i class="ti ti-calendar-plus"></i></div><div class="ui-dash-header-copy"><p class="ui-dash-eyebrow">Pinjaman</p><h1 class="ui-dash-title">Rescheduling</h1><p class="ui-dash-meta">Khusus Admin · KOL 2–4 · DPD tetap mengikuti tunggakan awal</p></div></header><?php ui_flash();?><div class="alert alert-info">Jadwal baru dimulai tujuh hari setelah diproses. Frekuensi tetap, tenor dan jumlah cicilan menjadi dua kali. Denda dilepas; bunga baru dibatasi pada keuntungan yang belum lunas dan dihitung ulang dari sisa pokok.</div>
<div class="card"><div class="table-responsive"><table class="table table-striped align-middle mb-0"><thead><tr><th>Anggota</th><th>Pinjaman</th><th>KOL / DPD</th><th>Sisa pokok</th><th>Keuntungan belum lunas</th><th>Tenor &amp; jadwal baru</th><th>Proses</th></tr></thead><tbody>
<?php foreach($data as $r):?><tr><td><?=htmlspecialchars($r['nama_lengkap'].' · '.$r['kode_anggota'])?></td><td><?=htmlspecialchars($r['kode_pinjaman'])?></td><td><span class="badge bg-warning text-dark">KOL <?=$r['kol']?></span> <?=$r['dpd']?> hari</td><td><?=formatRupiah($r['sisa_pokok'])?></td><td><?=formatRupiah($r['keuntungan_tersisa'])?></td><td><?=$r['tenor']?> → <?=$r['tenor_baru']?> bln · <?=$r['cicilan_baru']?> cicilan <?=htmlspecialchars($r['frekuensi'])?></td><td><form method="post" class="d-flex gap-2"><?=layananToken()?><input type="hidden" name="pinjaman_id" value="<?=(int)$r['id']?>"><input name="alasan" class="form-control form-control-sm" minlength="5" maxlength="2000" placeholder="Alasan rescheduling" required><button class="btn btn-sm btn-primary" onclick="return confirm('Buat kontrak rescheduling baru? Denda aktif akan dibebaskan.')">Proses</button></form></td></tr><?php endforeach?>
</tbody></table></div><?php if(!$data):?><div class="card-body text-muted">Tidak ada pinjaman KOL 2–4 yang memenuhi syarat.</div><?php endif?></div></div><?php include __DIR__.'/layout/shell_end.php';?></body></html>
